import time
from scapy.all import Dot11, Dot11Beacon, Dot11Elt, RadioTap, sendp

# Assumes 'nz_payload.py' generated by Kaitai exists in the exact same folder
try:
    from nz_payload import NzPayload
except ImportError:
    print("Error: Could not find 'nz_payload.py'. Generate it using: ksc -t python payload.ksy")
    exit(1)

# Hardware & Network Properties
INTERFACE = "wlan0mon"
BSSID = "00:1F:32:AA:BB:CC" 
SSID = "NintendoZone1"

# Assemble the cleartext data stream 
cleartext_nzone = bytearray(112)

url_target = b"http://192.168.1"
cleartext_nzone[0:len(url_target)] = url_target
cleartext_nzone[0x64] = 0x00    # DSi indicator
cleartext_nzone[0x65] = 0x00    # Open Network enum tracker
cleartext_nzone[0x66] = 0x01    # Blink activator bit
cleartext_nzone[0x6C] = 0x28    # Magic Marker 0x0428 (LE format)
cleartext_nzone[0x6D] = 0x04

# Standard Frame Check Sequence Math
def calculate_crc16(data: bytearray) -> int:
    crc = 0x0000
    for byte in data[:0x6E]:
        crc ^= (byte << 8)
        for _ in range(8):
            if crc & 0x8000:
                crc = (crc << 1) ^ 0x1021
            else:
                crc <<= 1
            crc &= 0xFFFF
    return crc

crc_val = calculate_crc16(cleartext_nzone)
cleartext_nzone[0x6E] = crc_val & 0xFF        
cleartext_nzone[0x6F] = (crc_val >> 8) & 0xFF

# =========================================================================
# INTEGRATE THE KAITAI ENGINE FOR ON-THE-FLY STRUCTURAL VALIDATION
# =========================================================================
print("[*] Passing generated buffer into compiled Kaitai class for parsing validation...")
try:
    # Wrap the cleartext bytes into sub-structure layer
    test_parse = NzPayload.NzoneDecryptedFrame.from_bytes(bytes(cleartext_nzone))
    
    print("--- [ Kaitai Verification Report ] ---")
    print(f" Parsed Target URL:  {test_parse.redirect_url}")
    print(f" Parsed System Flag: {hex(test_parse.system_flags)}")
    print(f" Parsed Magic Tag:   {hex(test_parse.magic_marker)} (Matches 0x428: {test_parse.magic_marker == 0x0428})")
    print(f" Parsed Checksum:    {hex(test_parse.sub_payload_crc16)}")
    print("--------------------------------------")
    print("[+] Structure checks passed. Initializing cipher pipeline.")
except Exception as e:
    print(f"[-] Kaitai Validation Crash! Your byte configuration is misaligned: {e}")
    exit(1)
# =========================================================================

# Cryptographic Bitwise Scrambling Pipeline
bssid_bytes = bytes.fromhex(BSSID.replace(":", ""))
xor_key = b"!SDW" + bssid_bytes[2:] 

encrypted_nzone = bytes(
    b ^ xor_key[i % len(xor_key)] for i, b in enumerate(cleartext_nzone)
)

# Management Beacon 
nintendo_ie = Dot11Elt(ID=221, info=b"\x00\x09\xbf" + encrypted_nzone)

packet = (
    RadioTap()
    / Dot11(type=0, subtype=8, addr1="ff:ff:ff:ff:ff:ff", addr2=BSSID, addr3=BSSID)
    / Dot11Beacon(cap="ESS", timestamp=int(time.time()), beacon_interval=100)
    / Dot11Elt(ID=0, info=SSID)
    / nintendo_ie
)

# Loop Broadcast Injection
print(f"\nInjecting verified Nintendo Zone beacons on {INTERFACE}...")
try:
    while True:
        sendp(packet, iface=INTERFACE, verbose=False)
        time.sleep(0.1)
except KeyboardInterrupt:
    print("\nBroadcasting stopped.")
